// `contains` on Vecs of numbers, strings, chars and bools is `includes`; floats keep Rust's
// NaN semantics. `sort()` of integers that are JS numbers and of strings uses plain comparators.
fn main() {
    let ints = vec![3, -7, 0, i32::MIN, i32::MAX, 42];
    println!("{} {} {} {} {}", ints.contains(&-7), ints.contains(&7), ints.contains(&0), ints.contains(&i32::MIN), ints.contains(&(-0)));
    let bigs: Vec<i64> = vec![1 << 40, -5, 0];
    let ubigs: Vec<u64> = vec![u64::MAX, 1];
    println!("{} {} {} {}", bigs.contains(&(1 << 40)), bigs.contains(&5), ubigs.contains(&u64::MAX), ubigs.contains(&0));
    let sizes: Vec<usize> = vec![0, 1, 1usize << 40];
    println!("{} {}", sizes.contains(&(1usize << 40)), sizes.contains(&2));
    let strs = vec!["a".to_string(), "bc".to_string(), "".to_string()];
    println!("{} {} {} {}", strs.contains(&"bc".to_string()), strs.contains(&"b".to_string()), strs.contains(&String::new()), strs.iter().any(|s| s == "a"));
    let chars = vec!['x', 'é', '\n'];
    println!("{} {} {}", chars.contains(&'é'), chars.contains(&'e'), chars.contains(&'\n'));
    let bools = vec![false];
    println!("{} {}", bools.contains(&false), bools.contains(&true));
    let floats = vec![1.5, f64::NAN, -0.0, f64::INFINITY];
    println!("{} {} {} {} {}", floats.contains(&1.5), floats.contains(&f64::NAN), floats.contains(&0.0), floats.contains(&-0.0), floats.contains(&f64::INFINITY));
    let pairs = vec![(1, "a"), (2, "b")];
    println!("{} {}", pairs.contains(&(2, "b")), pairs.contains(&(2, "a")));
    let opts = vec![Some(1), None];
    println!("{} {} {}", opts.contains(&None), opts.contains(&Some(1)), opts.contains(&Some(2)));
    let nested = vec![vec![1, 2], vec![]];
    println!("{} {}", nested.contains(&vec![1, 2]), nested.contains(&vec![1]));
    let slice: &[i32] = &ints[1..4];
    println!("{} {}", slice.contains(&0), slice.contains(&42));

    let mut a = vec![5, -1, 3, -1, 0, 2_000_000_000, -2_000_000_000, 7];
    a.sort();
    println!("{:?}", a);
    a.sort_unstable();
    a.reverse();
    println!("{:?}", a);
    let mut u: Vec<u32> = vec![4_000_000_000, 1, 0, 3_000_000_000];
    u.sort();
    println!("{:?}", u);
    let mut b: Vec<i64> = vec![1 << 40, -(1 << 41), 0, 5];
    b.sort();
    println!("{:?}", b);
    let mut ub: Vec<u64> = vec![u64::MAX, 0, 1 << 63];
    ub.sort_unstable();
    println!("{:?}", ub);
    let mut us: Vec<usize> = vec![1 << 50, 3, 1 << 20, 0];
    us.sort();
    println!("{:?}", us);
    let mut s8: Vec<i8> = vec![-128, 127, 0, -1];
    s8.sort();
    println!("{:?}", s8);
    let mut words = vec!["pear", "Apple", "apple", "fig", "", "zebra", "éclair"];
    words.sort();
    println!("{:?}", words);
    let mut owned: Vec<String> = words.iter().map(|w| w.to_uppercase()).collect();
    owned.sort_unstable();
    println!("{:?}", owned);
    let mut cs = vec!['z', 'a', 'é', '0', ' '];
    cs.sort();
    println!("{:?}", cs);
    let mut flags = vec![true, false, true];
    flags.sort();
    println!("{:?}", flags);
    let mut tuples = vec![(2, "b"), (1, "z"), (2, "a"), (1, "a")];
    tuples.sort();
    println!("{:?}", tuples);
    let mut opt = vec![Some(3), None, Some(-1)];
    opt.sort();
    println!("{:?}", opt);
    // Stability: equal keys keep their order.
    let mut recs = vec![(1, "first"), (0, "x"), (1, "second"), (0, "y"), (1, "third")];
    recs.sort_by_key(|r| r.0);
    println!("{:?}", recs);
    let mut by_len = vec!["ccc", "a", "bb", "dd", "e"];
    by_len.sort_by_key(|s| s.len());
    println!("{:?}", by_len);
    let mut big: Vec<i32> = (0..50_000).map(|i| (i * 7919) % 10_007 - 5000).collect();
    big.sort();
    println!("{} {} {} {}", big[0], big[25_000], big[49_999], big.windows(2).all(|w| w[0] <= w[1]));
    let mut fs = vec![2.5, -1.0, 0.0, -0.0, 10.0];
    fs.sort_by(|a, b| a.partial_cmp(b).unwrap());
    println!("{:?}", fs);
    let mut empty: Vec<i32> = Vec::new();
    empty.sort();
    println!("{:?} {}", empty, empty.contains(&1));
}
